);
INSERT OR REPLACE INTO site_content (key, data, updated_by, updated_at) VALUES ('main', '{"brandName":"HẢI DƯƠNG MEDIA","brandKicker":"Truyền thông và phát triển thương hiệu","heroEyebrow":"Đồng hành cùng doanh nghiệp trong kỷ nguyên số","heroTitle":"Giải pháp truyền thông giúp thương hiệu được nhìn thấy và ghi nhớ","heroDescription":"Từ chiến lược thương hiệu, nội dung, quảng cáo đến sản xuất hình ảnh và sự kiện. Mọi dịch vụ được triển khai trên một quy trình rõ ràng, dễ theo dõi.","primaryCta":"Nhận tư vấn","secondaryCta":"Khám phá dịch vụ","aboutTitle":"Một đối tác cho toàn bộ hành trình truyền thông","aboutBody":"Chúng tôi kết nối chiến lược, nội dung và thiết kế để doanh nghiệp truyền tải đúng thông điệp trên từng điểm chạm. Website này đang sử dụng nội dung mẫu và có thể cập nhật trực tiếp tại trang quản trị.","trustTitle":"Tập trung vào kết quả có thể theo dõi","trustBody":"Mỗi dự án bắt đầu bằng mục tiêu cụ thể, kế hoạch triển khai và các chỉ số cần đo lường. Doanh nghiệp luôn biết công việc đang ở đâu và bước tiếp theo là gì.","services":[{"title":"Booking quảng cáo","description":"Lập kế hoạch và triển khai quảng cáo báo chí, truyền hình, radio và nền tảng số."},{"title":"Sản xuất video","description":"Phim doanh nghiệp, TVC, video mạng xã hội và nội dung ghi hình sự kiện."},{"title":"Tổ chức sự kiện","description":"Xây dựng ý tưởng, kế hoạch truyền thông và vận hành chương trình theo mục tiêu."},{"title":"Tư vấn truyền thông","description":"Chiến lược thương hiệu doanh nghiệp, thương hiệu cá nhân và xử lý khủng hoảng."},{"title":"Thiết kế thương hiệu","description":"Logo, bộ nhận diện, hồ sơ năng lực, ấn phẩm và website doanh nghiệp."},{"title":"Sản xuất nội dung","description":"Bài PR, nội dung website, fanpage và kế hoạch nội dung đa kênh."}],"news":[{"id":"news-1","slug":"thuong-hieu-manh-quoc-gia-2027","category":"Kiến thức","title":"Xây dựng thương hiệu nhất quán trên nhiều kênh","excerpt":"Những nguyên tắc giúp doanh nghiệp giữ đúng thông điệp từ website đến mạng xã hội.","content":"Những nguyên tắc giúp doanh nghiệp giữ đúng thông điệp từ website đến mạng xã hội.Đề nghị điều chỉnh hoạt động giao, vận chuyển giấy tờ của shipper\n\n\n![Anh 1: CHi tiuey](data:image/jpeg;base64,)\n\n\n\nNam miền Bắc\n(Dân trí) - Đại biểu Quốc hội Nguyễn Minh Đức đặt vấn đề giấy tờ, tài liệu có thể chứa dữ liệu cá nhân hoặc bí mật kinh doanh, nếu shipper tự ý mở xem, đánh tráo thì trách nhiệm pháp lý như thế nào?.\nĐây là một trong những vấn đề được đặt ra tại phiên thảo luận tổ của Đoàn đại biểu Quốc hội TPHCM, khi thảo luận về dự án Luật Bưu chính sửa đổi, sáng 17/10.\n\nGiao - nhận giấy tờ chủ yếu dựa trên sự tin tưởng\n\nPhó Chủ nhiệm Ủy ban Quốc phòng, An ninh và Đối ngoại Nguyễn Minh Đức nêu khoảng trống pháp lý liên quan đến hoạt động vận chuyển hàng hóa, giấy tờ, tài liệu của các dịch vụ công nghệ, chẳng hạn các nền tảng giao hàng và đội ngũ shipper công nghệ, shipper tự do.\n\nÔng cho biết hiện nay, dịch vụ này không chỉ vận chuyển hàng hóa thông thường, mà còn nhận - chuyển các loại vật phẩm, ấn phẩm, tài liệu và giấy tờ.\n\nĐề nghị điều chỉnh hoạt động giao, vận chuyển giấy tờ của shipper - 1\nPhó Chủ nhiệm Ủy ban Quốc phòng, An ninh và Đối ngoại Nguyễn Minh Đức (Ảnh: Quang Phúc).\n\nVới doanh nghiệp đăng ký hoạt động vận chuyển theo quy định, việc điều chỉnh được thực hiện theo các luật có liên quan. Tuy nhiên, theo ông Đức, có những doanh nghiệp không đăng ký dịch vụ bưu chính nhưng vẫn vận chuyển giấy tờ, tài liệu dưới hình thức đơn hàng hoặc bưu gửi.\n\n“Trong trường hợp này, cơ sở pháp lý để điều chỉnh trách nhiệm của các bên chưa thật rõ ràng”, theo lời ông Đức.\n\nPhó Chủ nhiệm Ủy ban Quốc phòng, An ninh và Đối ngoại đặt vấn đề: Giấy tờ, tài liệu có thể chứa dữ liệu cá nhân, thông tin doanh nghiệp hoặc bí mật kinh doanh, nếu shipper tự ý mở xem, đánh tráo thì trách nhiệm pháp lý như thế nào?.\n\nTheo ông Đức, hoạt động vận chuyển hiện nay phần lớn dựa trên sự tin tưởng giữa người gửi và người nhận dịch vụ. Khi xảy ra rủi ro, việc xác định trách nhiệm và xử lý có thể gặp nhiều khó khăn.\n\nNhìn nhận đây là khoảng trống pháp lý cần được nghiên cứu, đại biểu Nguyễn Minh Đức đề nghị điều chỉnh lĩnh vực này, xác định những nội dung còn thiếu để nghiên cứu bổ sung vào dự thảo Luật Bưu chính, nếu cần thiết.\n\nGóp ý thêm việc sửa đổi Luật Bưu chính, đại biểu Đức cảnh báo tình trạng các đối tượng tội phạm lợi dụng lĩnh vực bưu chính để thực hiện hành vi phạm tội thông qua lợi dụng kẽ hở trong việc kiểm soát bưu gửi, vật phẩm, hàng hóa.\n\nVì vậy, theo ông, việc sửa đổi Luật Bưu chính lần này cần nâng cao hiệu quả quản lý, hạn chế thấp nhất rủi ro và tình trạng lợi dụng dịch vụ bưu chính để thực hiện hành vi vi phạm pháp luật.\n\nKhông để hậu kiểm tạo gánh nặng cho doanh nghiệp\n\nCùng tổ thảo luận, Chủ tịch Quốc hội Trần Thanh Mẫn ghi nhận những đột phá được xây dựng, trong đó điển hình là việc chuyển từ tiền kiểm, cấp phép sang hậu kiểm dựa trên dữ liệu.\n\nTheo Chủ tịch Quốc hội, đây là một thay đổi mang tính cách mạng. Dự thảo luật đã giảm 14 thủ tục hành chính xuống còn 1 thủ tục là đăng ký điện tử. “Nhưng hậu kiểm chỉ hiệu quả khi có dữ liệu thực và cơ chế giám sát đủ mạnh”, Chủ tịch Quốc hội lưu ý.\n\nĐề nghị điều chỉnh hoạt động giao, vận chuyển giấy tờ của shipper - 2\nChủ tịch Quốc hội Trần Thanh Mẫn phát biểu tại phiên thảo luận tổ sáng 17/10 (Ảnh: Quang Phúc).\n\nNếu hệ thống chia sẻ dữ liệu giữa doanh nghiệp và cơ quan quản lý chưa hoàn thiện hoặc tiêu chí mức độ rủi ro còn chung chung, Chủ tịch Quốc hội cho rằng hậu kiểm dễ trở thành hình thức hoặc tạo gánh nặng cho doanh nghiệp.\n\nMột vấn đề khác được Chủ tịch Quốc hội lưu ý là việc xác định phạm vi điều chỉnh và ranh giới pháp lý giữa dịch vụ bưu chính với hoạt động vận tải, kho bãi, logistics; quy định rõ nguyên tắc tối thiểu cần thiết, phân tầng rủi ro minh bạch, như dựa trên giá trị hàng hóa, loại hàng, lịch sử, người gửi, điểm đến để bảo vệ dữ liệu cá nhân.\n\nĐáng lưu ý, Chủ tịch Quốc hội cho rằng cần hoàn thiện cơ chế bồi thường thiệt hại theo hướng bảo vệ tốt hơn quyền lợi của người sử dụng dịch vụ.\n\nTheo đó, cần nghiên cứu cho phép người nhận có khoảng thời gian hợp lý, có thể là 24 hoặc 48 giờ, để kiểm tra hàng hóa, phát hiện những hư hỏng, mất mát bên trong bưu gửi mà không thể nhận biết ngay tại thời điểm giao nhận. Đồng thời, xem xét loại trừ giới hạn bồi thường trong trường hợp thiệt hại phát sinh do lỗi cố ý.\n\nDoanh nghiệp không vận hành trên mạng, Chủ tịch Quốc hội cho rằng cần quy trình hậu kiểm riêng, đơn giản hơn, tránh can thiệp sâu vào mô hình tổ chức của doanh nghiệp. \n\nTừ thực tiễn hơn 30 năm hoạt động trong lĩnh vực bưu chính, đại biểu Quốc hội Tào Đức Thắng, Chủ tịch Tập đoàn Viettel, đề nghị quy định doanh nghiệp bưu chính khác được sử dụng mạng bưu chính thông qua thỏa thuận, bảo đảm tuân thủ pháp luật về cạnh tranh.\n\nĐề nghị điều chỉnh hoạt động giao, vận chuyển giấy tờ của shipper - 3\nĐại biểu Quốc hội Tào Đức Thắng,  Chủ tịch Tập đoàn Viettel (Ảnh: Quang Phúc).\n\nTrung tướng Tào Đức Thắng nêu thực tế việc đầu tư hạ tầng viễn thông và bưu chính đòi hỏi nguồn lực rất lớn, thậm chí, để hình thành được hạ tầng vật lý, doanh nghiệp có thể phải đầu tư hàng chục tỷ USD.\n\n“Nếu một đơn vị đầu tư hạ tầng, trong khi các đơn vị khác không đầu tư được khai thác, kinh doanh trên hạ tầng đó mà không có cơ chế phù hợp, sẽ không khuyến khích các nhà đầu tư có tiềm lực đầu tư lớn và không bảo đảm cạnh tranh\", ông Thắng nêu quan điểm.\n\nBài viết hay? Ấn để tương tác","date":"16.10.2026","image":"/images/posts/post-thuong-hieu-manh.png","author":"Ban Biên Tập HẢI DƯƠNG MEDIA","link":"/tin-tuc/thuong-hieu-manh-quoc-gia-2027","active":true},{"id":"news-2","slug":"tet-ba-mien-chao-xuan-2027","category":"Góc nhìn","title":"Website doanh nghiệp cần chuẩn bị gì trước khi chạy quảng cáo","excerpt":"Một checklist ngắn để tránh lãng phí ngân sách và tăng tỷ lệ khách hàng liên hệ.","content":"Đại hội giao thương Tết Ba Miền 2027 sẽ diễn ra tại Trung tâm Hội nghị Quốc gia Hà Nội với nhiều nội dung đặc sắc: tọa đàm kinh tế vĩ mô, biểu diễn nghệ thuật mùa xuân và vinh danh thương hiệu tiêu biểu ASEAN.","date":"12.10.2026","image":"/images/posts/post-tet-3-mien.png","author":"Ban Sự Kiện","link":"/tin-tuc/tet-ba-mien-chao-xuan-2027","active":true},{"id":"news-3","slug":"lens-group-11-nam-he-sinh-thai","category":"Kinh nghiệm","title":"Cách biến một dịch vụ phức tạp thành nội dung dễ hiểu","excerpt":"Bắt đầu từ vấn đề của khách hàng, sau đó trình bày giải pháp bằng ngôn ngữ cụ thể.","content":"Được thành lập từ tình yêu cháy bỏng với con chữ và nghệ thuật kể chuyện thương hiệu, HẢI DƯƠNG MEDIA hôm nay đã trở thành tổ hợp truyền thông đa phương tiện sở hữu các ấn phẩm nổi tiếng và đối tác của hàng loạt đài truyền hình lớn.","date":"08.10.2026","image":"/images/posts/post-lens-11-nam.png","author":"Nguyễn Thu Len - CEO","link":"/tin-tuc/lens-group-11-nam-he-sinh-thai","active":true}],"hotline":"0900 000 000","hotlineHref":"+84900000000","email":"hello@example.com","address":"Cập nhật địa chỉ doanh nghiệp trong trang quản trị","zaloUrl":"https://zalo.me/84900000000","facebookUrl":"https://facebook.com","mapUrl":"https://maps.google.com","footerNote":"Nội dung hiện tại là bản mẫu và có thể chỉnh sửa trong trang quản trị.","bannerSlides":[{"id":"banner-1","tag":"VTV BROADCAST","title":"SẢN XUẤT PHIM QUẢNG CÁO & PHÁT SÓNG TRÊN VTV","highlight":"Đưa thương hiệu lên sóng truyền hình quốc gia VTV1, VTV3, VTV6","description":"Trọn gói từ kịch bản, sản xuất TVC chuẩn 4K, thông qua kiểm duyệt băng đài đến phát sóng các khung giờ vàng trước Thời sự 19h và Chuyển động 24h.","ctaText":"Xem bảng giá VTV","ctaHref":"#vtv-commercials","badge":"CHUẨN PHÁT SÓNG VTV","bgImage":"/images/vtv-studio.jpg","active":true},{"id":"banner-2","tag":"BOOKING PR / ADS","title":"BOOKING QUẢNG CÁO BÁO MẠNG TOÀN QUỐC","highlight":"Ưu đãi chiết khấu lên đến 51% tại các đầu báo hàng đầu","description":"Booking bài viết PR trên VnExpress, Dân Trí, Tuổi Trẻ, CafeF, Vie